suppressPackageStartupMessages(library(tidyverse))
a<-commandArgs(TRUE);root<-a[1];out<-a[2];z<-readRDS(file.path(root,'stage_a/neighborhood_cache.rds'));b<-z$base;p<-z$pts
h<-read_csv(file.path(root,'stage_h/matching/matched_pairs.csv'),show_col_types=FALSE);q<-read_csv(file.path(out,'combined_matched_pairs.csv'),show_col_types=FALSE);cv<-read_csv(file.path(root,'stage_b/eligibility_and_matching_status.csv'),show_col_types=FALSE);iso<-read_csv(file.path(root,'stage_j/matching/treated_surroundings_audit.csv'),show_col_types=FALSE)
expected<-h%>%filter(iso$isolated[match(treated_id,iso$tract_id)])
stopifnot(isTRUE(all.equal(as.data.frame(q),as.data.frame(expected),check.attributes=FALSE)),all(cv$clean_control[q$control_index]),all(cv$treated_complete[q$treated_index]),all(is.na(b$first_pis_year[q$control_index])|b$first_pis_year[q$control_index]>2019),all(b$first_pis_year[q$treated_index]==q$cohort),all(q$max_core_distance<=1+1e-12),!anyDuplicated(q[c('cohort','control_id')]))
idx<-match(b$tract_id,p$tract_id);la<-p$centroid_lat*pi/180;lo<-p$centroid_lon*pi/180
for(k in seq_len(nrow(q))){t<-q$treated_index[k];c<-q$control_index[k];ti<-idx[t];ci<-idx[c];dist<-2*6371.0088*asin(pmin(1,sqrt(sin((la[ci]-la[ti])/2)^2+cos(la[ci])*cos(la[ti])*sin((lo[ci]-lo[ti])/2)^2)));stopifnot(dist>14,length(intersect(z$members[['7']][[t]],z$members[['7']][[c]]))==0,substr(sprintf('%011.0f',q$treated_id[k]),1,2)==substr(sprintf('%011.0f',q$control_id[k]),1,2))}
writeLines(c('PASS: filtered 7 km H pairs retain exact original controls; no rematching.', 'PASS: same-state, distance >14 km, nonoverlap, core caliper, no within-cohort reuse.', 'PASS: never/future controls, clean entire control regions and complete treated regions.', 'PASS: treated 2011–2019, no surrounding known 2010–2019 projects or unknown timing.'),file.path(out,'INDEPENDENT_VALIDATION.txt'))
